import{_ as t,o as a,c as r,ae as n}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Semantic layer over Vinted","description":"","frontmatter":{"title":"Semantic layer over Vinted"},"headers":[],"relativePath":"projects/vinted-semantic-layer/index.md","filePath":"projects/vinted-semantic-layer/index.md"}'),i={name:"projects/vinted-semantic-layer/index.md"};function o(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="semantic-layer-over-vinted" tabindex="-1">Semantic layer over Vinted <a class="header-anchor" href="#semantic-layer-over-vinted" aria-label="Permalink to &quot;Semantic layer over Vinted&quot;">​</a></h1><p><em>Work in progress. Notes only.</em></p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Vinted is a second-hand marketplace organised primarily around keyword search and category browsing. For buyers looking for something specific — a particular garment type, material, era, or condition — discovery depends on how sellers title and tag their listings. There is no underlying product ontology. Similar items are separated by inconsistent vocabulary; unrelated items cluster under shared keywords.</p><p>The result is search that behaves like an index over unstructured text rather than like navigation through a curated catalogue. This is a general problem in unstructured marketplaces, but it is particularly visible in fashion, where the meaningful dimensions of a garment — cut, fabric, construction, provenance — are rarely captured in a listing title.</p><h2 id="the-approach" tabindex="-1">The approach <a class="header-anchor" href="#the-approach" aria-label="Permalink to &quot;The approach&quot;">​</a></h2><p>The experiment aims to build a semantic layer between the marketplace&#39;s raw listings and a query interface that understands garment structure. The layer would extract or infer attributes from listing text and images, map them to a controlled vocabulary, and expose search and browse paths that follow garment semantics rather than seller phrasing.</p><p>Concretely: a listing described as &quot;vintage 90s wool blazer brown&quot; and one described as &quot;brown wool jacket 1990s&quot; should resolve to comparable attribute sets, regardless of title wording. Browse paths like &quot;structured outerwear → wool → 1990s&quot; should be possible even when no seller used those terms.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p>This is early-stage work. The attribute vocabulary is under development. Extraction from listing text is partially prototyped; image-based inference is not yet attempted. There is no public interface. These notes record the problem framing and intended direction rather than results.</p><hr><p><em>Work in progress. Incomplete.</em></p>',12)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
